func ProcessWithdrawals(st state.BeaconState, executionData interfaces.ExecutionData) (state.BeaconState, error) {
    expectedWithdrawals, processedPartialWithdrawalsCount, err := st.ExpectedWithdrawals()
    if err != nil {
